#!/usr/bin/env node
/**
 * Parse goldens for assets/js/lib/zoneparse.js — one human-diffable line per item.
 *
 *   node tests/fixtures/zones/gen-parse-golden.mjs            # compare, print a unified diff, exit 1 on change
 *   node tests/fixtures/zones/gen-parse-golden.mjs --write    # rewrite expected/*.parse.golden.txt
 *   node tests/fixtures/zones/gen-parse-golden.mjs --split    # rebuild cloudflare-api-page1/2.json from cloudflare-api.json
 *
 * Golden format:
 *   format bind dialect cloudflare origin example.com (header, high)
 *   rr www.example.com. 300~ A 192.0.2.10 ; proxied ; @35        (300~ = Cloudflare "Auto" TTL)
 *   rr api.example.com. - A - ; alias elb dualstack.x.elb.amazonaws.com. ; @8
 *   issue info CF_SOA_OWNER_UNDOTTED @27 name=example.com
 * The analysis goldens (lint, seeds, origins, hand-off) live next to these, generated by the
 * zonelint / zoneorigins owner; a parser change reruns both generators in the same change.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { parseZone, zoneNames } from '../../../assets/js/lib/zoneparse.js';

export const ZONES_DIR = dirname(fileURLToPath(import.meta.url));

/**
 * Every fixture with its parse options. `files` (several) are concatenated with '\n' and parsed
 * once, as the zone view does for several Cloudflare API pages.
 */
export const FIXTURES = Object.freeze([
  { id: 'cloudflare-export', files: ['cloudflare-export.txt'] },
  { id: 'cloudflare-api', files: ['cloudflare-api.json'] },
  { id: 'cloudflare-api-page1', files: ['cloudflare-api-page1.json'] },
  { id: 'cloudflare-api-page2', files: ['cloudflare-api-page2.json'] },
  { id: 'cloudflare-api-pages', files: ['cloudflare-api-page1.json', 'cloudflare-api-page2.json'] },
  { id: 'route53', files: ['route53.json'] },
  { id: 'example.com.yaml', files: ['example.com.yaml'] },
  { id: 'bind-edge', files: ['bind-edge.zone.txt'] },
  { id: 'cpanel-example.com.db', files: ['cpanel-example.com.db.txt'] },
  { id: 'directadmin-example.com.db', files: ['directadmin-example.com.db.txt'] },
  { id: 'godaddy', files: ['godaddy.txt'] },
  { id: 'cli53', files: ['cli53.txt'] },
  { id: 'plesk-info', files: ['plesk-info.txt'] },
  { id: 'internal', files: ['internal.zone.txt'] },
  { id: 'placeholder.cf', files: ['placeholder.cf.txt'] },
  { id: 'axfr-dig', files: ['axfr-dig.txt'] },
  { id: 'bad-unterminated-quote', files: ['bad/unterminated-quote.txt'] },
  { id: 'bad-unbalanced-paren', files: ['bad/unbalanced-paren.txt'] },
  { id: 'bad-include', files: ['bad/include.txt'] },
  { id: 'bad-inventory', files: ['bad/inventory.csv'] },
  { id: 'bad-cert.pem', files: ['bad/cert.pem.txt'] },
  { id: 'bad-yaml-anchor', files: ['bad/yaml-anchor.yaml'] },
  { id: 'bad-yaml-block-scalar', files: ['bad/yaml-block-scalar.yaml'] },
  { id: 'bad-yaml-proto', files: ['bad/yaml-proto.yaml'], opts: { origin: 'example.com' } },
  { id: 'bad-json-proto', files: ['bad/json-proto.json'] }
]);

/** Read a fixture's text (several files joined with '\n'). */
export function fixtureText(fx) {
  return fx.files.map((f) => readFileSync(join(ZONES_DIR, f), 'utf8')).join('\n');
}

/** Parse a fixture exactly as the goldens do. */
export function parseFixture(fx) {
  return parseZone(fixtureText(fx), { filename: fx.files[0].split('/').pop(), ...(fx.opts || {}) });
}

export function goldenPath(fx) {
  return join(ZONES_DIR, 'expected', `${fx.id}.parse.golden.txt`);
}

const fqdn = (n) => (n === '.' ? '.' : `${n}.`);

function param(v) {
  return typeof v === 'string' ? (/[\s=]/.test(v) || v === '' ? JSON.stringify(v) : v) : JSON.stringify(v);
}

function issueLine(prefix, w) {
  const params = Object.keys(w.params || {}).map((k) => `${k}=${param(w.params[k])}`).join(' ');
  return `${prefix} ${w.severity} ${w.code} @${w.line}${params ? ` ${params}` : ''}`;
}

function recordLine(r) {
  const ttl = r.ttl === null ? '-' : `${r.ttl}${r.ttlAuto ? '~' : ''}`;
  const ann = [];
  if (r.proxied === true) ann.push('proxied');
  if (r.proxied === false) ann.push('dns-only');
  if (r.proxiable === false) ann.push('not-proxiable');
  if (r.flattenCname) ann.push('flatten');
  if (r.alias) ann.push(`alias ${r.alias.provider} ${fqdn(r.alias.target)}${r.alias.evaluateTargetHealth ? ' eval-health' : ''}`);
  if (r.routing) {
    const extra = ['weight', 'region', 'failover'].filter((k) => r.routing[k] !== undefined).map((k) => `${k}=${r.routing[k]}`);
    if (r.routing.geo) extra.push(`geo=${JSON.stringify(r.routing.geo)}`);
    if (r.routing.healthCheck) extra.push('health-check');
    ann.push(`routing ${r.routing.policy}:${r.routing.id ?? '-'}${extra.length ? ` ${extra.join(' ')}` : ''}`);
  }
  if (r.intendedName) ann.push(`intended ${r.intendedName}`);
  if (r.intendedTargets) ann.push(`intended-targets ${r.intendedTargets.join(',')}`);
  if (r.occludedBy) ann.push(`occluded-by ${r.occludedBy}`);
  if (r.invalid) ann.push('invalid');
  if (r.unsupported) ann.push('unsupported');
  if (r.generated) ann.push('generated');
  if (r.duplicateOf !== undefined) ann.push(`dup-of #${r.duplicateOf}`);
  if (r.tags) ann.push(`tags ${JSON.stringify({ ...r.tags })}`);
  if (r.comment) ann.push(`comment ${JSON.stringify(r.comment)}`);
  ann.push(`@${r.line}`);
  return `rr ${fqdn(r.name)} ${ttl} ${r.type} ${r.text || '-'} ; ${ann.join(' ; ')}`;
}

/**
 * The golden text of one parsed zone.
 * @param {object} zone
 * @returns {string}
 */
export function formatParseGolden(zone) {
  const out = [];
  out.push(`format ${zone.format ?? '-'} dialect ${zone.dialect ?? '-'} origin ${zone.origin ?? '-'} (${zone.originSource ?? '-'}, ${zone.originConfidence})`);
  if (zone.markers.length) out.push(`markers ${zone.markers.join(' | ')}`);
  if (zone.fatal) {
    out.push(issueLine('fatal', zone.fatal));
    return `${out.join('\n')}\n`;
  }
  const s = zone.stats;
  out.push(`stats records=${s.records} proxied=${s.proxied} dns-only=${s.dnsOnly} entries=${s.entries} skipped=${s.skipped} generated=${s.generated} lines=${s.lines}`);
  out.push(`types ${Object.keys(s.byType).sort().map((t) => `${t}=${s.byType[t]}`).join(' ')}`);
  out.push(`owners ${zoneNames(zone).length}`);
  out.push(`partial ${zone.partial}`);
  if (zone.defaultTtl !== null) out.push(`default-ttl ${zone.defaultTtl}`);
  for (const r of zone.records) out.push(recordLine(r));
  for (const w of zone.warnings) out.push(issueLine('issue', w));
  return `${out.join('\n')}\n`;
}

/** Minimal unified diff (line LCS; fixtures are small). */
export function unifiedDiff(a, b, name) {
  const x = a.split('\n');
  const y = b.split('\n');
  const n = x.length;
  const m = y.length;
  const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) dp[i][j] = x[i] === y[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const lines = [`--- ${name} (expected)`, `+++ ${name} (actual)`];
  let i = 0;
  let j = 0;
  while (i < n || j < m) {
    if (i < n && j < m && x[i] === y[j]) {
      i++;
      j++;
    } else if (j < m && (i >= n || dp[i][j + 1] >= dp[i + 1][j])) lines.push(`+${y[j++]}`);
    else lines.push(`-${x[i++]}`);
  }
  return lines.join('\n');
}

/** cloudflare-api.json → page1 (first 10 rows) and page2 (row 10 again + the rest + 3 new rows). */
export function splitCloudflarePages() {
  const src = JSON.parse(readFileSync(join(ZONES_DIR, 'cloudflare-api.json'), 'utf8'));
  const rows = src.result;
  const extra = [
    { id: '0000000000000000000000000000a101', name: 'blog.example.com', type: 'CNAME', content: 'example-blog.github.io', proxiable: true, proxied: false, ttl: 1, settings: {}, meta: {}, comment: null, tags: [] },
    { id: '0000000000000000000000000000a102', name: 'v6only.example.com', type: 'AAAA', content: '2001:db8::77', proxiable: true, proxied: false, ttl: 1, settings: {}, meta: {}, comment: null, tags: [] },
    { id: '0000000000000000000000000000a103', name: 'mail.example.com', type: 'A', content: '198.51.100.25', proxiable: true, proxied: false, ttl: 1, settings: {}, meta: {}, comment: null, tags: [] }
  ];
  const total = rows.length + extra.length;
  const page = (result, n) => ({
    result, success: true, errors: [], messages: [],
    result_info: { page: n, per_page: 10, count: result.length, total_count: total, total_pages: 2 }
  });
  const p1 = page(rows.slice(0, 10), 1);
  const p2 = page([rows[9], ...rows.slice(10), ...extra], 2);
  const write = (file, obj) => writeFileSync(join(ZONES_DIR, file), `{\n  "result": [\n${obj.result.map((r) => `    ${JSON.stringify(r)}`).join(',\n')}\n  ],\n  "success": true,\n  "errors": [],\n  "messages": [],\n  "result_info": ${JSON.stringify(obj.result_info)}\n}\n`);
  write('cloudflare-api-page1.json', p1);
  write('cloudflare-api-page2.json', p2);
}

function main(argv) {
  if (argv.includes('--split')) {
    splitCloudflarePages();
    console.log('wrote cloudflare-api-page1.json, cloudflare-api-page2.json');
  }
  const write = argv.includes('--write');
  let changed = 0;
  for (const fx of FIXTURES) {
    const actual = formatParseGolden(parseFixture(fx));
    const path = goldenPath(fx);
    const expected = existsSync(path) ? readFileSync(path, 'utf8') : '';
    if (actual === expected) continue;
    changed++;
    if (write) {
      writeFileSync(path, actual);
      console.log(`updated expected/${fx.id}.parse.golden.txt`);
    } else {
      console.log(unifiedDiff(expected, actual, `expected/${fx.id}.parse.golden.txt`));
    }
  }
  if (!changed) console.log(`all ${FIXTURES.length} parse goldens match`);
  return write || !changed ? 0 : 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = main(process.argv.slice(2));
}
